// Per-space hosted legal pages (issue #184): privacy / terms / refund.
// Each page is either auto-generated by the LLM or written manually by the
// merchant, with the content stored here and rendered on the public page
// ({space}.jomform.com/privacy, /terms, /refund).
package dbstore

import (
	"context"
	"errors"
)

// LegalPageType enumerates the three hosted legal page kinds.
const (
	LegalPagePrivacy = "privacy"
	LegalPageTerms   = "terms"
	LegalPageRefund  = "refund"
)

// LegalPageMode is how a page's content was produced.
const (
	LegalModeAuto   = "auto"   // generated by the LLM
	LegalModeManual = "manual" // written by the merchant
)

// ErrLegalPageNotFound is returned when a space has no content for a page
// type (the public route 404s).
var ErrLegalPageNotFound = errors.New("legal page not set")

// LegalPage is one hosted legal page for a space.
type LegalPage struct {
	SpaceID  string `json:"space_id"`
	PageType string `json:"page_type"`
	Mode     string `json:"mode"`
	Content  string `json:"content"`
}

// LegalPage reads one legal page for a space. Returns ErrLegalPageNotFound
// when the page has no stored content (not set).
func (s *SpaceStore) LegalPage(ctx context.Context, spaceID, pageType string) (*LegalPage, error) {
	p := &LegalPage{SpaceID: spaceID, PageType: pageType}
	err := s.pool.QueryRow(ctx,
		`SELECT mode, content FROM space_legal_pages WHERE space_id=$1 AND page_type=$2`,
		spaceID, pageType).Scan(&p.Mode, &p.Content)
	if err != nil {
		return nil, err
	}
	if p.Content == "" {
		return nil, ErrLegalPageNotFound
	}
	return p, nil
}

// LegalPages reads all three legal pages for a space (empty content when not
// set). Used by the settings UI to show current state.
func (s *SpaceStore) LegalPages(ctx context.Context, spaceID string) (map[string]*LegalPage, error) {
	out := map[string]*LegalPage{
		LegalPagePrivacy: {SpaceID: spaceID, PageType: LegalPagePrivacy, Mode: LegalModeManual},
		LegalPageTerms:   {SpaceID: spaceID, PageType: LegalPageTerms, Mode: LegalModeManual},
		LegalPageRefund:  {SpaceID: spaceID, PageType: LegalPageRefund, Mode: LegalModeManual},
	}
	rows, err := s.pool.Query(ctx,
		`SELECT page_type, mode, content FROM space_legal_pages WHERE space_id=$1`,
		spaceID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	for rows.Next() {
		var pt, mode, content string
		if err := rows.Scan(&pt, &mode, &content); err != nil {
			return nil, err
		}
		if p, ok := out[pt]; ok {
			p.Mode = mode
			p.Content = content
		}
	}
	return out, rows.Err()
}

// SaveLegalPage upserts one legal page's content + mode.
func (s *SpaceStore) SaveLegalPage(ctx context.Context, p *LegalPage) error {
	_, err := s.pool.Exec(ctx,
		`INSERT INTO space_legal_pages (space_id, page_type, mode, content, updated_at)
		 VALUES ($1,$2,$3,$4, now())
		 ON CONFLICT (space_id, page_type) DO UPDATE SET
		   mode=EXCLUDED.mode, content=EXCLUDED.content, updated_at=now()`,
		p.SpaceID, p.PageType, p.Mode, p.Content)
	return err
}
